// BullMQ — Production Task Queue (Node.js + Redis)
import { Queue, Worker, QueueEvents } from 'bullmq';
import IORedis from 'ioredis';

const connection = new IORedis(process.env.REDIS_URL);

// ── PRODUCER: enqueue jobs from your API ───────────────────────
const emailQueue = new Queue('email', { connection });

async function enqueueWelcomeEmail(userId, email) {
  await emailQueue.add(
    'welcome',
    { userId, email },
    {
      attempts: 5,                // retry up to 5 times
      backoff: { type: 'exponential', delay: 1000 }, // 1s, 2s, 4s, 8s, 16s
      removeOnComplete: 100,      // keep last 100 completed jobs
      removeOnFail: 500,          // keep last 500 failed jobs for inspection
      jobId: `welcome-${userId}`, // deduplication key — prevents duplicate jobs
    }
  );
}

// ── CONSUMER: worker process ───────────────────────────────────
const worker = new Worker(
  'email',
  async (job) => {
    const { userId, email } = job.data;
    console.log(`Processing job ${job.id}, attempt ${job.attemptsMade + 1}`);

    // Transient failures (network, rate limit) cause retries.
    // Permanent failures (invalid email) should throw a non-retryable error.
    await sendEmail({ to: email, template: 'welcome', userId });
  },
  {
    connection,
    concurrency: 10,              // process 10 jobs simultaneously
    limiter: { max: 100, duration: 60_000 }, // 100 emails/minute (rate limit)
  }
);

// ── MONITORING: observe job lifecycle ─────────────────────────
const queueEvents = new QueueEvents('email', { connection });
queueEvents.on('completed', ({ jobId }) =>
  console.log('Job completed', jobId));
queueEvents.on('failed', ({ jobId, failedReason }) =>
  console.error('Job failed', jobId, failedReason));

// Dead-letter pattern: inspect permanently failed jobs
const failed = await emailQueue.getFailed(0, 50);
for (const job of failed) {
  console.error('Dead job:', job.id, job.failedReason);
  // alert on-call, move to DLQ table, trigger manual review
}
